body:
The encoding of attribute names and filenames in the Content-Disposition field of multipart sections does not work correctly for UTF-8 characters. To be more precise: Not for any non-ASCII chars.

The specification is not clear to me. But the reality, as defined by Firefoy and MSIE is as follows:

The attribute name and filename values are encoded as defined by the HTML page which contains the POST form. Normally as UTF-8.

This test class generates file upload multipart requests with attribute name, filename and file content in three different encodings (ASCII, UTF-8, ISO-8859-1).

The request is generated with HttpPostRequestEncoder and then parsed with HttpPostRequestDecoder. The unit tests checks, if all special characters are correctly found in the result.

``` java
package org.jboss.netty.handler.codec.http.multipart;

import static org.junit.Assert.*;

import java.nio.charset.Charset;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.jboss.netty.buffer.ChannelBuffer;
import org.jboss.netty.buffer.ChannelBuffers;
import org.jboss.netty.handler.codec.http.*;
import org.junit.Ignore;
import org.junit.Test;

public class HttpPostRequestEncoderTest {

    @Test
    public void testFilenameEncoding_ASCII() throws Exception {
        testFilenameEncoding("abc*123&ABC xyz&XYZ", Charset.forName("ASCII"));
    }

    @Test
    public void testFilenameEncoding_utf8() throws Exception {
        testFilenameEncoding("华语", Charset.forName("UTF-8")); // UTF-8 encoding: e5 8d 8e e8 af ad
    }

    @Test
    public void testFilenameEncoding_iso8859_1() throws Exception {
        testFilenameEncoding("äöüÄÖÜß", Charset.forName("ISO-8859-1"));
    }

    public void testFilenameEncoding(String special, Charset charset) throws Exception {

        HttpDataFactory factory = new DefaultHttpDataFactory(DefaultHttpDataFactory.MINSIZE);
        HttpRequest request = new DefaultHttpRequest(HttpVersion.HTTP_1_1, HttpMethod.POST, "http://localhost/upload");
        HttpPostRequestEncoder encoder = new HttpPostRequestEncoder(factory, request, true, charset);

        String name = "NAME-"+special+"-NAME";
        String file = "FILE-"+special+"-FILE";
        String value = "VALUE-"+special+"-VALUE";

        FileUpload fileUpload = factory.createFileUpload(
                request, name, file, "text/plain",
                null, charset, value.getBytes(charset).length);
        fileUpload.setContent(ChannelBuffers.copiedBuffer(value.getBytes(charset)));

        encoder.addBodyHttpData(fileUpload);
        encoder.finalizeRequest();

        int contentLength = Integer.parseInt(request.getHeader(HttpHeaders.Names.CONTENT_LENGTH));

        HttpChunk chunk = encoder.nextChunk();

        byte[] content = getChannelBufferContent(chunk.getContent());
        String encodedRequest = new String(content, charset);
        System.out.println("Encoded multipart content:\n"+encodedRequest);

        assertEquals(content.length, contentLength);

        assertEquals(special, getTaggedContent(encodedRequest, "VALUE"));
        assertEquals(special, getTaggedContent(encodedRequest, "NAME"));
        assertEquals(special, getTaggedContent(encodedRequest, "FILE"));


        HttpPostRequestDecoder decoder = new HttpPostRequestDecoder(factory, request, charset);
        decoder.offer(chunk);
        while (!chunk.isLast()) {
            chunk = encoder.nextChunk();
            decoder.offer(chunk);
        }

        List<InterfaceHttpData> httpDatas = decoder.getBodyHttpDatas();
        assertEquals(1, httpDatas.size());
        assertTrue(httpDatas.get(0) instanceof FileUpload);

        FileUpload extracted = (FileUpload)httpDatas.get(0);
        assertEquals(name, extracted.getName());
        assertEquals(file, extracted.getFilename());
        assertEquals(value, new String(getChannelBufferContent(extracted.getChannelBuffer()), charset));
    }

    @Ignore @Test
    public void testPattern() {
        String content = "a\r\nTAG-abc-TAG\r\nb";
        assertEquals("abc", getTaggedContent(content, "TAG"));
    }

    private String getTaggedContent(String encodedRequest, String tag) {
        Pattern pattern = Pattern.compile(".*"+tag+"-(.*)-"+tag+".*", Pattern.DOTALL);
        Matcher matcher = pattern.matcher(encodedRequest);
        if (matcher.matches()) {
            return matcher.group(1);
        }
        return null;
    }

    private byte[] getChannelBufferContent(ChannelBuffer channelBuffer) {
        byte[] content = new byte[channelBuffer.readableBytes()];
        channelBuffer.getBytes(channelBuffer.readerIndex(), content);
        return content;
    }

}
```

The test fails in the current "3" branch for the name and filename attributes in UTF-8 and ISO-8859-1 encoding.
